fn diagflat(v: Vec<f32>) -> Vec<Vec<f32>> {
    let n = v.len();
    let mut matrix: Vec<Vec<f32>> = Vec::with_capacity(n);
    for i in 0..n {
        matrix.push(create_row(&v, i));
    }
    matrix
}

fn create_row(v: &Vec<f32>, i: usize) -> Vec<f32> {
    let n = v.len();
    // Initialize a row of length n with all 0.0
    let mut row = vec![0.0f32; n];
    // Place the i-th element of v on the diagonal position
    row[i] = v[i];
    row
}

